pragma solidity ^0.8.0;
contract Vault {
  mapping(address => uint) public balances;
  function withdraw() external {
    uint amount = balances[msg.sender];
    (bool ok, ) = msg.sender.call{value: amount}("");
    require(ok);
    balances[msg.sender] = 0;
  }
  function deposit() external payable { balances[msg.sender] += msg.value; }
}

pragma solidity ^0.8.0;
contract Token {
  mapping(address => uint) public balanceOf;
  address public owner;
  function mint(address to, uint amount) external {
    balanceOf[to] += amount;
  }
  function burn(address from, uint amount) external {
    balanceOf[from] -= amount;
  }
}

pragma solidity ^0.7.0;
contract Auction {
  uint public end;
  uint public highestBid;
  address public highestBidder;
  function bid() external payable {
    require(block.timestamp < end, "ended");
    require(msg.value > highestBid);
    payable(highestBidder).transfer(highestBid);
    highestBid = msg.value;
    highestBidder = msg.sender;
  }
}

pragma solidity ^0.8.0;
contract Random {
  function pick(address[] calldata entrants) external view returns (address) {
    uint idx = uint(keccak256(abi.encodePacked(block.timestamp, block.difficulty))) % entrants.length;
    return entrants[idx];
  }
}

pragma solidity ^0.8.0;
import "./IERC20.sol";
contract Swap {
  function swap(address from, address to, IERC20 tokenIn, IERC20 tokenOut, uint amount) external {
    tokenIn.transferFrom(from, address(this), amount);
    tokenOut.transfer(to, amount);
  }
}

pragma solidity ^0.8.0;
contract Wallet {
  address public owner;
  constructor() { owner = msg.sender; }
  function execute(address target, bytes calldata data) external returns (bytes memory) {
    require(tx.origin == owner, "not owner");
    (bool ok, bytes memory ret) = target.call(data);
    require(ok);
    return ret;
  }
}
